import{_ as l,o as a,c as t,a2 as r}from"./chunks/framework.F7eQ-ohH.js";const e="/bzygq/assets/quesion_imgs_37efe09aacc04ffb9a28b1816592698c.CUhS7vh4.png",s="/bzygq/assets/quesion_imgs_06fdfc395b8a4bc0bfdd88965a2595af.BnotCSPP.png",_=JSON.parse('{"title":"3.应届生央企接offer Check List","description":"","frontmatter":{},"headers":[],"relativePath":"docs/体检&入职/3.应届生央企接offer Check List.md","filePath":"docs/体检&入职/3.应届生央企接offer Check List.md","lastUpdated":1788883925000}'),i={name:"docs/体检&入职/3.应届生央企接offer Check List.md"};function n(p,o,c,f,h,d){return a(),t("div",null,[...o[0]||(o[0]=[r('<h1 id="_3-应届生央企接offer-check-list" tabindex="-1">3.应届生央企接offer Check List <a class="header-anchor" href="#_3-应届生央企接offer-check-list" aria-label="Permalink to &quot;3.应届生央企接offer Check List&quot;">​</a></h1><p>最近有同学拿下央企的offer，但是对于工资、福利以及和HR怎么沟通这块儿有些疑惑来问我，我想了一下应该很多应届生同学都有这样的疑惑。这个公司待遇怎么样？稳定性好不好？会不会很卷之类的？因此，我这个文档主要是给大家写清楚，接央国企Offer之前有哪些需要问的问题，以及为啥要问这些问题？</p><p><img src="'+e+'" alt=""></p><h1 id="一、工资和福利相关问题" tabindex="-1">一、工资和福利相关问题 <a class="header-anchor" href="#一、工资和福利相关问题" aria-label="Permalink to &quot;一、工资和福利相关问题&quot;">​</a></h1><p>很多央企、国企回答待遇问题支支吾吾半天，然后只能给你说个总包，比如告诉你20万、30万啥的，感觉好像里面有诈一样。</p><p>其实不是这样的，因为央企、国企的工资构成五花八门，有可能你的HR确实都不搞清楚你每年到手能有多少，但是一半面试、HR给你承诺的总包是能达到的。</p><p>比如：有的童鞋可能总包20w，但是每个月只发8000，然后感觉怎么也不可能到20万的年包对吧？其实不是这样的，每个月给你8000，然后公积金4000~5000，年终再发个10万，这样一算才到HR说那个20万的总包。</p><p>但是如果大家想谨慎一点，问清楚一点，就可以询问以下问题，确保不会踩坑。</p><ol><li><strong>工资的Base是多少？总包是多少？</strong></li></ol><p>这里的Base是指你每个有的工资基数，一半是由：<strong>基本工资+岗位工资+月度绩效</strong>构成，一般来说央企基本工资不会很高，到手就7000~10000。然后总包是指你一年的税前工资，月base发不够的基本就是年终奖补给你。</p><ol><li><strong>补贴（如住房、交通、通讯、餐补等）具体都有哪些？</strong></li></ol><p>都说央企福利待遇好，其实就是补贴多，住房补助一般是应届生有，例如某航天央企入职前5年2k/月的房补，还是自己公司的1室1厅。交通、通讯补助以我前司为例，大概分别是400/月，餐补800/月，这部分是不算入总包的一般（但是还是看HR的人品，算到总包就有点儿傻逼了）。</p><ol><li><strong>确认试用期薪资是否打折？转正后调薪机制（是否与职级、绩效挂钩）？</strong></li></ol><p>国企试用期通常3-6个月，薪资不低于转正后80%，所以可以问问试用期工资到底会不会打折，以及转正之后的工资是不是会根据职级和绩效重新确定工资。</p><ol><li><strong>确定五险一金缴纳比例？</strong></li></ol><p>这里最重要的其实是确定住房公积金比例是否是24%，以及缴纳基数是多少，很多央企优势就在于24%的住房公积金了，这个一定要问清楚。其它的医保、失业保险啥的都差不多不用问。</p><ol><li><strong>确定其它福利？是否有企业年金、补充医疗保险、工会福利等。</strong></li></ol><p>好的央企是会有企业年金、补充医疗保险（是否覆盖家属）、年度体检、节日福利、住房补贴/宿舍、子女教育补贴、工会福利（如购物卡、文体活动）等，所以可以沟通的时候问问清楚。</p><ol><li><strong>问问年假规则、请假规则（也可以不问）</strong></li></ol><p>来央国企咱们就图一个稳定、轻松，所以关于请假的问题可以提前问问HR，比如流程严格不大，年假几天啊，入职当年是否享受年假、申请流程、是否需多层审批。</p><h1 id="二、岗位与工作内容" tabindex="-1">二、岗位与工作内容 <a class="header-anchor" href="#二、岗位与工作内容" aria-label="Permalink to &quot;二、岗位与工作内容&quot;">​</a></h1><ol><li><strong>问清楚岗位以及所属部门？</strong></li></ol><p>接受offer前一定问清楚岗位所属部门、汇报对象、核心工作内容，避免“岗位名称与实际工作脱节”，如招聘时写“技术岗”，实际分配至行政岗。这都算好的，难受的是招聘进去是技术岗，结果分配到打杂岗就很难受。</p><ol><li><strong>搞清楚是否有轮岗？</strong></li></ol><p>询问是否有轮岗，这点非常重要，因为很多国企常通过轮岗培养人才，说是培养人才，但是轮岗容易把人搞废，比如你做技术的，去轮岗柜员几年，那你的技术恐怕都忘完了，所以需确认轮岗周期及是否自愿。</p><ol><li><strong>问问职业发展体系，职级评定、绩效等</strong></li></ol><p>简单问问晋升体系，比如职级评定标准：年限、绩效、领导评价、内部竞聘机制是否公平透明这些问题吧，一般来说央国企内的竞赛跟个人努力没啥太大的关系。</p><h1 id="三、编制与合同性质" tabindex="-1">三、编制与合同性质 <a class="header-anchor" href="#三、编制与合同性质" aria-label="Permalink to &quot;三、编制与合同性质&quot;">​</a></h1><ol><li><strong>问清楚你的编制和合同类型</strong></li></ol><p>国企编制、合同五花八门，有的老牌一点儿的央企还会发编制，但是社招的一般是劳务派遣，正式编制员工在福利、晋升上更有优势，劳务派遣则可能存在差异。说人话就是劳务派遣企业一有风吹草动，裁员的就是你，而应届生进去一般是正式员工，非常安全。</p><ol><li><strong>问清楚是否签订就业服务期限？如果提前离职是否需要赔钱？</strong></li></ol><p>有的同学可能去央企国企只是为了拿下一个户口，所以对于“校招/社招正式员工”来说，一定要确认是否需签订《服务期协议》如解决落户、提供专项培训等可能约定最低服务年限，以及工作没满足最低服务期限是否需要赔偿企业钱这个事情。</p><ol><li><strong>其它问问试用期时长、违约条款等？</strong></li></ol><p>试用期时长的话国企一般不超过6个月、转正考核标准（是否一票否决制）。违约金条款需要明确是不是有如“提前离职赔X万”可能无效之类的条款。</p><h1 id="四、工作时间与考勤" tabindex="-1">四、工作时间与考勤 <a class="header-anchor" href="#四、工作时间与考勤" aria-label="Permalink to &quot;四、工作时间与考勤&quot;">​</a></h1><ol><li><strong>问清楚工作时间、加班时长（最好找内部人问清楚）</strong></li></ol><p>确认上下班时间，是否严格打卡，国企部分岗位可能弹性工作制、加班频率及补偿，加班是否调休或按倍数支付工资，避免“隐性加班”的情况。</p><ol><li><strong>问问工作地点与出差频率</strong></li></ol><p>一定问清楚办公地点，是否可能异地调动，因为很多央企，尤其是工程类、分支机构较多的国企、所以一定问清楚出差频率及补贴标准，否则长期在外面出差的话家里人也受不了。</p><h1 id="五、入职准备与材料-可不问" tabindex="-1">五、入职准备与材料（可不问） <a class="header-anchor" href="#五、入职准备与材料-可不问" aria-label="Permalink to &quot;五、入职准备与材料（可不问）&quot;">​</a></h1><ol><li><strong>必备材料</strong></li></ol><ul><li>提前确认档案转移流程（国企通常有人事档案管理权，需开具调档函）、党组织关系转移（党员需办理介绍信）、体检要求（指定医院或常规项目）。</li><li>若为应届生，确认报到证、三方协议签署细节（是否影响干部身份）。</li></ul><ol><li><strong>其他注意事项</strong></li></ol><ul><li>询问入职前是否需提前实习或参加培训、办公设备（如电脑、邮箱账号）的发放流程。</li></ul><h1 id="六、一些切实的建议" tabindex="-1">六、一些切实的建议 <a class="header-anchor" href="#六、一些切实的建议" aria-label="Permalink to &quot;六、一些切实的建议&quot;">​</a></h1><ol><li><strong>工资待遇、加班情况一定想办法找内部人问问</strong></li></ol><p>央企和央企之间的差距比人和狗之间都大，有些HR可能就不是人，为了把你忽悠进来完成绩效无所不用其极，比如给你承诺10000的base，结果入职后只有6k是有这种可能性的，加班同理，为了以防外一大家一定想办法找找内部的人问问。</p><ol><li><strong>口头承诺不要信，要求书面留痕！！！</strong></li></ol><p>接上面说，有些HR可能就不是人，满口胡话，而且打死不发微信、邮件，沟通薪资就是打电话，这种央企、国企一般就有问题。确认工资这些信息的时候，一定要要求书面留痕迹，不然极有可能进去工资和口头承诺对不上号，别到时候再哭爹喊娘。（当然，你手里没啥选择的话，就不要提这种无理要求了）</p><ol><li><strong>平衡心态很重要，工作嘛有舍有得！</strong></li></ol><p>国企优势在于稳定性和资源平台，但可能存在流程较慢、创新空间有限等特点，提前评估是否与职业规划匹配，不要进去国企之后又嫌弃钱少，这就很不理智了。</p><h1 id="央国企知识星球" tabindex="-1">央国企知识星球 <a class="header-anchor" href="#央国企知识星球" aria-label="Permalink to &quot;央国企知识星球&quot;">​</a></h1><p>欢迎各位校招/社招想去央企、国企的朋友加入的<a href="https://mp.weixin.qq.com/s?__biz=MzkzMjI0MDY3Mw==&amp;mid=2247485557&amp;idx=1&amp;sn=ff41558a80b34e37a7c8c4c4823e2b9f&amp;chksm=c25f843bf5280d2d9b7a9170c4d2d2d95253f7035fbb03a05d8de01b9798a0d001cf4c3464d0#rd" target="_blank" rel="noreferrer">知识星球</a>，大多数的人进不去国企并不是学历、能力不够，而是缺乏渠道及时获取央国企招聘信息和准备策略。为了帮助大家系统准备央国企招聘，up搭建了一个全国性的央国企招聘就业的知识星球。</p><p>星球内部包含中国石油、国家电网、中国烟草等垄断央企的笔试/面试题目以及解析，还包含中航工业、中国电科、中国五矿等航天、矿业央企准备的技术路线等。</p><p>还会每天推送全国各地的央国企招聘信息，帮助大家及时获取各地的央国企的投递机会，不错过每一个招聘信息，成功帮助非常多小伙伴找到了合适的央企工作。</p><p>欢迎各位感兴趣的同学加入体验，微信扫描下方二维码，可以直接加入：</p><p><img src="'+s+'" alt=""></p>',57)])])}const b=l(i,[["render",n]]);export{_ as __pageData,b as default};
